def ensure_env():
    required={'numpy':'2.1.3','pandas':'2.3.3','scipy':'1.15.3',
              'scikit-learn':'1.6.1','tensorflow':'2.20.0','keras':'3.13.2'}
    missing=[]
    for name,v in required.items():
        try:version=importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:version=None
        if version!=v:missing.append(f'{name}=={v}')
    if missing:
        if not OPTIONS['INSTALL_MATCHING_ENVIRONMENT']:
            raise RuntimeError('Kaggle versions differ: '+repr(missing))
        print('Installing locked experiment dependencies:',missing,flush=True)
        subprocess.run([sys.executable,'-m','pip','install','-q','--disable-pip-version-check',*missing],check=True)
    for name,v in required.items():
        if importlib.metadata.version(name)!=v:raise RuntimeError('Restart kernel to activate '+name+'=='+v)

def run():
    seeds=OPTIONS['RUN_SEEDS']
    if not seeds or len(set(seeds))!=len(seeds) or any(x not in [42,2026,3407,123,777] for x in seeds):
        raise RuntimeError('Seed assignment incorrect.')
    ensure_env()
    base=Path(OPTIONS['OUTPUT_DIR']);runtime=base/'runtime';runtime.mkdir(parents=True,exist_ok=True)
    for name,b64,sha in EMBEDDED:
        content=zlib.decompress(base64.b64decode(b64))
        if hashlib.sha256(content).hexdigest()!=sha:raise RuntimeError('Wrong embedded source SHA '+name)
        target=runtime/name
        if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest()!=sha:
            raise RuntimeError('Changed runtime code in existing output; stop to protect results')
        target.write_bytes(content)
    code=base/'code';code.mkdir(exist_ok=True)
    for name in ['training_engine.py','fusion_extension.py','fusion_six_driver.py','f06_seven_components_driver.py']:
        code.joinpath(name).write_bytes(runtime.joinpath(name).read_bytes())
    import importlib.util
    spec=importlib.util.spec_from_file_location('f06_meta',runtime/'training_engine.py')
    mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
    protocol=mod.decode_protocol()
    cfg=dict(base=str(base),data_csv=OPTIONS['DATA_CSV'],MODE=OPTIONS['MODE'],
         stage='NEURAL',version='HYSCF_F06_7COMPONENT_TFIDF10000_V1',
         engine_sha256=EMBEDDED[0][2],embedded_sha256={n:s for n,b,s in EMBEDDED},
         protocol_sha256=protocol['protocol_sha256'],data_sha=protocol['csv_sha256'],
         classes=protocol['classes'],tfidf_sizes=[10000],run_only_seeds=seeds,
         warm_timing_repeats=3,keep_completed_optimizer_state=False,
         deadline=time.time()+OPTIONS['MAX_RUNTIME_HOURS']*3600)
    path=runtime/'config.json';path.write_text(json.dumps(cfg,indent=2))
    print('Account',OPTIONS['ACCOUNT'],'SEEDS',seeds,'MODELS',7*len(seeds),flush=True)
    print('Dataset SHA256 must match the archived F06 protocol; no new splitting.',flush=True)
    subprocess.run([sys.executable,str(runtime/'f06_seven_components_driver.py'),'--config',str(path)],check=True)
    print('Finished. Results and full-model ZIPs are under /kaggle/working',flush=True)
run()
